REV=[
('R01','Separate identity levels','Agent, chemical substance, product, package and external code were mixed.','Use radiopharmaceutical, molecular_entity, medicinal_product, product_package and external_identifier records.','A package code cannot identify a chemical structure; RxNorm IN/PIN/SCD/SBD and NDC product/package levels must be explicit.'),
('R02','Represent identifiers as strings','Several blueprint identifiers use float types.','Store codes as strings with scheme, version, semantic level and review state.','Preserves leading zeros and long identifiers, and avoids spreadsheet numerical rounding.'),
('R03','Separate regulation from identification','NDC is listed among regulatory identifiers and approval is a single status.','Use dated, jurisdiction-specific regulatory_authorization records and separate identifier assignments.','NDC listing does not establish FDA approval; applications, authorization holders and reference products have distinct roles.'),
('R04','Normalize ingredients and molecular roles','Active ingredient, precise ingredient, excipient and moiety recur in multiple sections.','Use product_ingredient roles and typed molecular component links.','One ingredient identity can be reused across products without duplicating its chemical definition.'),
('R05','Separate specification from physical unit','Packaging attributes, calibration activity and fill volume share one block.','Keep nominal package specifications apart from batch and radiopharmaceutical_unit measurements.','The same package presentation can contain many units with different activities, timestamps and expiries.'),
('R06','Add manufacturing and QC provenance','The initial model lacks executable batch-level assay structure.','Add material_lot, preparation_event and radiopharmaceutical_test; retain batch disposition separately.','A test needs subject, method, result status, unit, reference time and specification; pending sterility is not a failed test or an automatic release decision.'),
('R07','Distinguish specific and molar activity','The blueprint places both in radionuclide properties; the legacy batch field combines them.','Use separate timed test records for specific activity and molar activity with chemical denominator.','Bq/g and Bq/mol are different quantities, depend on chemical species and reference time, and are not nuclide constants.'),
('R08','Normalize nuclear decay data','Branch probabilities, emission intensities and daughter chains are not clearly separated.','Use radionuclide and decay_emission with branch fraction, yield per decay, energy kind and daughter links.','A photon yield is not a decay-branch probability; physical decay is not biological metabolism.'),
('R09','Give PK and binding measurements context','Absorption, distribution, metabolism and binding entries combine multiple quantities.','Use one contextual reference test per quantity, linked to evidence; use existing patient measurements and TACs for individuals.','Species, matrix, organ, time, method, statistic and analyte basis determine meaning; cohort summaries are not patient observations.'),
('R10','Keep clinical events in existing nodes','Blueprint safety, response and dose fields overlap the Lu177-PSMA model.','Reuse measurement, anatomic_target, time_activity_curve, absorbed_dose, toxicity_event, response_assessment and survival_outcome.','Avoids a parallel patient model and preserves the revised multidimensional outcome framework.'),
('R11','Add the operational medication chain','IDRP describes procurement, prescription, dispensing and MAR separately.','Add supply_offer, radiopharmaceutical_order, dispense_event and traceable unit links to administration.','Records what was requested, prepared, dispensed and actually administered without assuming these quantities are equal.'),
('R12','Separate human clinical and research scopes','IDRP excludes preclinical work; the blueprint includes preclinical and digital-twin research.','Declare human clinical, reference/preclinical and computational research profiles.','No animal or in-vitro result is silently treated as an individual human measurement.'),
('R13','Represent computation independently','AI readiness, PBPK and prediction fields are mixed with reference agent attributes.','Add computational_model, model_run, model_parameter and model_prediction with information cutoff and input provenance.','Predictions remain distinct from measured dose and clinical decisions; readiness scores require named rubrics.'),
('R14','Separate structural links from ontology axioms','The source lists ontology-style predicates beside data elements.','Implement typed record links where appropriate and retain conceptual assertions for separately curated ontology mappings.','A Gen3 foreign-key-like link does not establish OWL equivalence, causal claims or class subsumption.'),
('R15','Version and review the evidence','Definitions, example codes and numerical examples are preliminary.','Retain source row/paragraph, definition, revision rationale and mapping review state; do not populate unverified clinical defaults.','Source examples and proposed mappings are not validated terminology, consensus, product labeling or prescribing instructions.'),
('R16','Make quantities unambiguous','Half-life, fractions, dose quantities and units are inconsistent in some rows.','Distinguish biological/physical/effective half-life; fraction/percent; absorbed dose/BED/EQD2; mass/moles; observed/predicted quantities.','Unit conversion requires a defined quantity, denominator, time basis and model assumptions.'),
('R17','Retain the Gen3 integration contract','MIDRC measurements require patient-related parent links.','Preserve existing nodes, properties, enums and link groups; reuse applicable scalar definitions in a separate nonpatient test node.','Batch QC cannot be submitted as a patient measurement without inventing a case or weakening the upstream schema.'),
('R18','Resolve duplicate and empty source entries','Duplicate follows_regulatory_pathway, repeated route/excipient fields, a placeholder and an empty pharmacodynamics heading occur.','Consolidate equivalent destinations, retain all source occurrences and add contextual pharmacodynamic evidence records.','Traceability is preserved without creating a second meaning for repeated labels or treating a work-allocation note as a clinical field.'),
]
REV=[dict(revision_id=a,title=b,source_issue=c,proposed_revision=d,rationale=e,status='Proposed for working-group review') for a,b,c,d,e in REV]

def rows(d):
    for sh in d['sheets']:
        for r in sh['rows']:
            n=r['row'];yield n,{k.rstrip('0123456789'):v['value'] for k,v in r['cells'].items()},sh['name']
def target(dest):
    n,p=dest.split('.',1);assert n in S and p in S[n]['properties'],dest
    return {'node':n,'property':p}
def add(source,row,cells,sheet,dest,rev,reason='',fixed=None,alternatives=(),status='proposed',definition=''):
    d=target(dest);fixed=fixed or {};options=[d]+[target(v) for v in alternatives]
    f=dict(source_element_id=f'{source}:r{row}',source_sheet=f'{source} / {sheet}',source_row=row,source_name=cells.get('C',cells.get('B','')),source_definition=definition or cells.get('D','') if source=='nk_blueprint' else definition,source_data_type=cells.get('E','') if source=='nk_blueprint' else 'Not supplied',source_allowed_values=cells.get('G','') if source=='nk_blueprint' else '',source_unit='',**d,fixed_values=fixed,destination_options=options,transformation=reason or next(v['rationale'] for v in REV if v['revision_id']==rev),mapping_status=status,nuclex_mapping_status='unmapped',nuclex_concept_id=None,revision_id=rev)
    f['source_definition']=str(f['source_definition'] or '')
    ROWS.append(f)

